mapper.select:
SELECT q.quiz_id, q.course_id, c.title AS course_title, q.title, q.time_limit, q.total_marks, q.start_time, q.end_time, q.status, q.created_by, a.full_name AS creator_name FROM quiz q LEFT JOIN course c ON q.course_id = c.course_id LEFT JOIN account a ON q.created_by = a.account_id WHERE 1 = 1
AND q.course_id = #{courseId}
AND q.status = #{status}
ORDER BY q.created_at DESC
